        long res = 1;
        long base = g % p;
        long exp = n;
        while (exp > 0) {
            if ((exp % 2) == 1) {
                res = (res * base) % p;
            }
            base = (base * base) % p;
            exp = exp / 2;
        }
        return (int) res;
    }
}

